import { test, expect } from '@playwright/test';

test.describe('Filter Tag Removal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/search'); // Replace with the actual URL of the search page
  });

  test('should display filter tags', async ({ page }) => {
    const filterTag = await page.getByText('Sample Filter Tag'); // Replace with actual filter tag text
    await expect(filterTag).toBeVisible();
  });

  test('should remove filter tag when x icon is clicked', async ({ page }) => {
    const filterTag = await page.getByText('Sample Filter Tag'); // Replace with actual filter tag text
    const removeIcon = filterTag.locator('xpath=./following-sibling::button[@aria-label="Remove"]'); // Adjust the selector based on your HTML structure

    await expect(filterTag).toBeVisible();
    await removeIcon.click();
    await expect(filterTag).not.toBeVisible();
  });
});
